import os

def _find_source():
    names = ("source.mp3", "source.wav", "source.m4a", "source.mp4", "source.flac", "source.ogg")
    d = os.getcwd()
    for _ in range(6):
        for n in names:
            p = os.path.join(d, n)
            if os.path.isfile(p):
                return p
        # also scan any source.* in this dir
        try:
            for f in os.listdir(d):
                low = f.lower()
                if low.startswith("source.") and low.rsplit(".", 1)[-1] in (
                    "mp3", "wav", "m4a", "mp4", "flac", "ogg", "aac", "webm"):
                    return os.path.join(d, f)
        except OSError:
            pass
        nd = os.path.dirname(d)
        if nd == d:
            break
        d = nd
    raise FileNotFoundError("找不到 source.* 影音檔(已向上層搜尋)")

def _fmt(t):
    if t is None or t < 0:
        t = 0.0
    h = int(t // 3600)
    m = int((t % 3600) // 60)
    s = int(t % 60)
    ms = int(round((t - int(t)) * 1000))
    if ms == 1000:
        ms = 0
        s += 1
    return "%02d:%02d:%02d,%03d" % (h, m, s, ms)

src = _find_source()
from faster_whisper import WhisperModel
model = WhisperModel("small", device="cpu", compute_type="int8")
segments, info = model.transcribe(src, language="zh", beam_size=5)

lines = []
idx = 1
for seg in segments:
    text = (seg.text or "").strip()
    lines.append(str(idx))
    lines.append("%s --> %s" % (_fmt(seg.start), _fmt(seg.end)))
    lines.append(text)
    lines.append("")
    idx += 1

with open("raw.srt", "w", encoding="utf-8") as f:
    f.write("\n".join(lines))
print("wrote raw.srt with %d segments from %s" % (idx - 1, os.path.basename(src)))
